from core import *

@register('limits','stationary-phase-root-geometry','oscillatory-stationary-phase-localization','nonstationary-cancellation-and-local-Fresnel-scaling','Only stationary points survive square-root normalization; one must separate nonstationary cancellation, signed Jacobians, and half-contributions at endpoints.','The critical-level derivative problem counts positive sublevel mass; this limit relies on conditional oscillatory cancellation and a Fresnel integral.',[{'caseId':'stationary-geometry-'+str(i),'roots':roots,'bounds':bounds,'weight':w,'purpose':'Change multiple stationary points, endpoint geometry, and signed amplitude.'} for i,(roots,bounds,w) in enumerate([([0],[-1,2],'1+x'),([-1,1],[-2,2],'1+x**2'),([0,2],[0,3],'2+x'),([-1,0,2],[-1,3],'3+x'),([0,1],[0,1],'1+x'),([-2,1],[-2,1],'3+x**2'),([-1,0,1],[-2,2],'2+x**2'),([-2,0,3],[-3,3],'4+x')])],['integration by parts','stationary phase','Fresnel integral','local inverse functions'])
def stationary(case):
 roots=case['roots'];lo,hi=case['bounds'];P=s.prod(x-r for r in roots);w=s.sympify(case['weight'],locals={'x':x});terms=[]
 for r in roots:
  d=s.diff(P,x).subs(x,r);sides=R(1,2) if r in [lo,hi] else 1;terms.append(sides*w.subs(x,r)/abs(d));ck('The phase has a nondegenerate minimum at root '+str(r),s.diff(P**2,x,2).subs(x,r),2*d*d)
 A=s.sqrt(pi/2)*sum(terms);wrongSquares=s.sqrt(pi/2)*sum((R(1,2) if r in [lo,hi] else 1)*w.subs(x,r)/s.diff(P,x).subs(x,r)**2 for r in roots)
 # There can also be stationary points where P' vanishes and P does not. The phase there contributes O(n^-1/2) with an oscillating phase, ruining a limit! Use cutoff support to exclude them explicitly.
 # Instead integrate cos(n u^2) with root-local coordinate neighborhoods defined by disjoint monotone branches.
 intervals=[]
 for idx,r in enumerate(roots):
  delta=min([R(1,4)]+[R(abs(r-q),4) for q in roots if q!=r]);left=max(s.Integer(lo),r-delta);right=min(s.Integer(hi),r+delta)
  intervals.append((left,right))
  poly=s.Poly(s.diff(P,x),x);condition('No extra stationary point on the selected root neighborhood',poly.count_roots(left,right)==0,'The explicitly listed intervals are disjoint monotone branches of the root polynomial.')
 analytic('Localized stationary phase',['Integration is over the explicitly listed disjoint root neighborhoods. On every neighborhood the root polynomial has one simple zero and has no derivative zero. The amplitude is polynomial.'],['Split each neighborhood into a smaller root neighborhood and the remaining compact pieces. Integration by parts using the nonzero phase derivative bounds every remaining piece by O(1/n).','Use u=P(x) locally. The transformed smooth amplitude at u=0 is w(r)/|P prime(r)|. After v=sqrt(n)u, the constant amplitude contributes the full-line Fresnel cosine integral sqrt(pi/2), or half of it at an endpoint.','The nonconstant amplitude contribution is o(n^-1/2), obtained by one integration by parts away from a small scaled neighborhood and then continuity of the amplitude.','The Fresnel value follows by damping exp(i v^2) with exp(-epsilon v^2), evaluating the Gaussian with the square root of epsilon-i having positive real part, and taking the improper limit using uniform oscillatory tail bounds.'])
 region=r'\cup'.join('['+L(a)+','+L(b)+']' for a,b in intervals)
 return candidate(r'R(x)='+L(P)+r',\quad w(x)='+L(w)+r',\quad E='+region+r'.\qquad\lim_{n\to\infty}\sqrt n\int_Ew(x)\cos(nR(x)^2)\,\mathrm dx',A,[(2*A,'Count each endpoint as a second full neighborhood and double all contributions'),(A/2,'Use a half-line Fresnel contribution at every interior point'),(A*s.sqrt(2),'Use the full Gaussian constant in place of the Fresnel cosine constant'),(A/s.sqrt(2),'Apply the real-part factor twice'),(wrongSquares,'Use the square of the local derivative rather than its magnitude in the Jacobian'),(pi*sum(terms),'Confuse the Fresnel integral with the Dirichlet sine integral')],[T('The explicitly listed intervals contain one simple zero each and no other stationary point. Away from those roots, integration by parts gives a contribution of order the reciprocal of n.'),r'R(x)=R\prime(r)(x-r)+O((x-r)^2),\qquad u=R(x)',r'\int_{-\infty}^{\infty}\cos(v^2)\,\mathrm dv=\sqrt{\frac\pi2}',T('This improper Fresnel value follows from a damped complex Gaussian and oscillatory tail bounds. Each interior root contributes its amplitude divided by the magnitude of the local derivative, times the full Fresnel value. An endpoint contributes half.'),r'\lim_{n\to\infty}\sqrt n\int_Ew(x)\cos(nR(x)^2)\,\mathrm dx=\sqrt{\frac\pi2}\left('+r'+'.join(L(q) for q in terms)+r'\right)='+L(A)],'localized-multiple-stationary-points-Fresnel-limit')

@register('limits','quadratic-gauss-magnitude','quadratic-residue-sum-parity-interference','square-modulus-and-character-orthogonality','Squaring the oscillatory sum exposes an exact congruence condition. Even moduli have an additional surviving character whose phase either reinforces or cancels the main one.','Continuous stationary phase estimates local oscillations; this finite lattice sum has exact arithmetic interference and parity obstructions.',[{'caseId':'repeat-'+str(a)+'-mod4-'+str(r),'a':a,'r':r,'purpose':'Change period multiplicity and the parity class that controls exact cancellation.'} for a,r in [(1,0),(1,1),(2,0),(2,3),(3,0),(3,2),(5,1),(5,2)]],['complex exponentials','roots of unity','finite character sums','subsequence limits'])
def gauss(case):
 a=case['a'];r=case['r'];factor=2 if r==0 else 0 if r==2 else 1;A=s.sqrt(a*factor)
 # Avoid unreliable floating cancellation: reduce exponents modulo the modulus and reduce the resulting polynomial modulo its cyclotomic polynomial.
 Z=s.Symbol('Z')
 for N in [1,2,3]:
  m=4*N+r;mod=a*m;poly=sum(Z**((a*k*k)%mod) for k in range(mod));conj=sum(Z**((-a*k*k)%mod) for k in range(mod));res=s.rem(s.expand(poly*conj-a*a*m*factor),s.cyclotomic_poly(mod,Z),Z);ck('Independent exact cyclotomic reduction of the squared magnitude at modulus '+str(mod),res,0)
 analytic('Exact quadratic Gauss magnitude',['The complex exponential has its usual single-valued meaning; the modulus is a positive integer in the displayed fixed congruence class.'],['First split the sum into the displayed number of identical periods, reducing it to G_m=sum exp(2pi i k^2/m).','Write the squared magnitude as a double sum and set one index equal to the other plus h. The inner geometric character sum vanishes unless m divides2h.','For odd m only h=0 survives, giving m. For even m, h=m/2 also survives and contributes m exp(pi i m/2), giving2m if m is divisible by4 and zero if it is congruent to2 modulo4.','The displayed normalization then gives the exact value for every index, hence its limit.'])
 return candidate(r'm_n=4n+'+str(r)+r',\quad N_n='+str(a)+r'm_n,\quad S_n=\sum_{k=0}^{N_n-1}\exp\left(\frac{2\pi i\,'+str(a)+r'k^2}{N_n}\right),\qquad i^2=-1.\qquad\lim_{n\to\infty}\frac{|S_n|}{\sqrt{N_n}}',A,[(s.sqrt(a),'Use the odd-modulus answer in every parity class'),(s.sqrt(2*a),'Always reinforce the extra even-modulus character'),(s.Integer(0),'Always cancel the extra even-modulus character'),(s.Integer(a),'Forget to take the square root of the period multiplicity'),(s.sqrt(R(a,2)),'Halve the squared character count'),(s.sqrt(4*a),'Double the reinforced squared magnitude'),(s.sqrt(R(a,4)),'Apply the normalization square root twice')],[r'G_m=\sum_{k=0}^{m-1}e^{2\pi i k^2/m},\qquad S_n='+str(a)+r'G_{m_n}',r'|G_m|^2=\sum_{h=0}^{m-1}e^{2\pi i h^2/m}\sum_{k=0}^{m-1}e^{2\pi i(2h)k/m}',T('The inner character sum is zero unless the modulus divides twice the shift. The surviving shifts are zero and, only for even moduli, half the modulus.'),r'|G_m|^2=\begin{cases}m&m\textnormal{ odd}\\2m&m\equiv0\pmod4\\0&m\equiv2\pmod4\end{cases}',r'm_n\equiv'+str(r)+r'\pmod4,\qquad\frac{|S_n|}{\sqrt{N_n}}='+L(A)],'quadratic-Gauss-magnitude-exact-parity-cancellation')

@register('limits','reinforced-urn-distribution','Polya-exchangeability-beta-limit','exchangeable-draw-count-and-Riemann-density','Reinforcement destroys independent binomial sampling. The ordered-draw weights are exchangeable, producing a beta-binomial count law and a nondegenerate limiting density.','The central-limit family concerns independent fluctuations; this process retains a random limiting proportion instead of concentrating at its initial mean.',[{'caseId':'urn-'+str(a)+'-'+str(b)+'-cut-'+str(q),'a':a,'b':b,'q':str(q),'purpose':'Asymmetric initial compositions and distinct thresholds avoid a symmetry-only answer.'} for a,b,q in [(1,2,R(1,2)),(2,1,R(1,3)),(2,3,R(1,2)),(3,2,R(2,3)),(3,4,R(1,3)),(4,2,R(1,2)),(2,4,R(2,3)),(4,3,R(1,2))]],['conditional probability','exchangeability','beta integrals','weak convergence'])
def urn(case):
 a=case['a'];b=case['b'];q=R(case['q']);norm=s.factorial(a+b-1)/(s.factorial(a-1)*s.factorial(b-1));density=norm*x**(a-1)*(1-x)**(b-1);A=s.integrate(density,(x,q,1))
 def countprob(N,k):return s.binomial(N,k)*s.rf(a,k)*s.rf(b,N-k)/s.rf(a+b,N)
 dist=[s.Integer(1)]
 for N in range(1,7):
  nxt=[s.Integer(0)]*(N+1)
  for k,v in enumerate(dist):nxt[k]+=v*R(b+N-1-k,a+b+N-1);nxt[k+1]+=v*R(a+k,a+b+N-1)
  for k,v in enumerate(nxt):ck('Independent urn transition agrees with exchangeable count law '+str(N)+','+str(k),v,countprob(N,k))
  dist=nxt
 ck('The proposed limiting density has unit mass',s.integrate(density,(x,0,1)),1)
 analytic('Beta-binomial law and density limit',['Initially there are the displayed positive integer counts of two colors. Each draw is uniform, the drawn ball is returned, and one additional ball of its color is added.'],['Every ordered draw string with k red and n-k blue draws has the same probability: the product of red rising factors times blue rising factors divided by the total rising factors. Count the binomial number of such strings.','For positive integer initial counts, factorial cancellation gives a polynomial-in-k,n representation. Uniformly on compact subintervals of(0,1), n times the mass at k tends to the beta density.','The same explicit polynomial bounds control the endpoint mass by a constant times the endpoint interval length to the corresponding positive initial exponent. Thus Riemann sums converge on the full interval, and the continuous limiting density has no atom at the threshold.','The actual red fraction differs from k/n by O(1/n), so it has the same limiting tail probability.'])
 return candidate(T('An urn initially contains '+str(a)+' red balls and '+str(b)+' blue balls. On every draw, choose a ball uniformly, return it, and add one more ball of the same color. Let the red fraction after n draws be ')+r'X_n.'+T('Find ')+r'\lim_{n\to\infty}\mathbb P(X_n>'+L(q)+r').',A,[(1-A,'Return the complementary lower-tail probability'),(R(a,a+b),'Use the initial mean as a tail probability'),(s.integrate(x**(a-1)*(1-x)**(b-1),(x,q,1)),'Omit the beta normalization'),(s.integrate(norm*x**(b-1)*(1-x)**(a-1),(x,q,1)),'Swap the initial color counts'),(s.integrate(density,(x,0,q*q)),'Square the threshold and take the wrong tail'),(A/2,'Halve the tail mass at a point with no limiting atom'),((1+A)/2,'Average the tail with one as though half the mass were an endpoint atom')],[r'K_n=\textnormal{number of red draws},\qquad\mathbb P(K_n=k)=\binom nk\frac{('+str(a)+r')_k('+str(b)+r')_{n-k}}{('+str(a+b)+r')_n}',r'(c)_j=c(c+1)\cdots(c+j-1),\quad(c)_0=1',T('The ordered draw probability depends only on the number of red draws, not their order. This gives the displayed exchangeable count law.'),r'n\mathbb P(K_n=k)\longrightarrow '+L(density.subs(x,t))+r'\quad\textnormal{when }k/n\to t\in(0,1)',T('Factorial cancellation bounds the endpoint portions as well, so these masses converge by Riemann sums to the density below. The actual red fraction differs from the draw fraction by a quantity tending uniformly to zero.'),r'\rho(t)='+L(density.subs(x,t))+r',\qquad\lim\mathbb P(X_n>'+L(q)+r')=\int_{'+L(q)+r'}^1\rho(t)\,\mathrm dt='+L(A)],'reinforced-urn-asymmetric-beta-tail-limit')

@register('limits','matrix-commutator-limit','noncommuting-small-loop-limit','second-order-commutator-and-accumulated-log-error','Four first-order matrix perturbations cancel, leaving a second-order noncommutative drift. Its remainder must stay negligible after taking a growing power.','The demoted fixed-Jordan family uses a finite binomial formula; this needs a cancellation scale and control of a product of noncommuting factors.',[{'caseId':'shears-'+str(a)+'-'+str(b),'a':str(a),'b':str(b),'purpose':'Different signed shear interactions, including negative commutator drift.'} for a,b in [(1,2),(2,3),(R(1,2),3),(R(2,3),2),(-1,2),(2,-3),(R(-1,2),3),(R(3,2),-1)]],['matrix products','matrix exponential','commutators','uniform remainder estimates'])
def commutator(case):
 a=R(case['a']);b=R(case['b']);h=s.symbols('h',real=True);U=s.Matrix([[1,a*h],[0,1]]);V=s.Matrix([[1,0],[b*h,1]]);C=s.expand(U*V*U.inv()*V.inv());B=s.diag(a*b,-a*b);A=s.exp(a*b)
 ck('The full four-factor product has the asserted quadratic drift',s.diff(C,h,2).subs(h,0)/2,B)
 ck('Every first-order term cancels',s.diff(C,h).subs(h,0),s.zeros(2))
 ck('Independent commutator of the two tangent matrices gives the same drift',s.diff(U,h).subs(h,0)*s.diff(V,h).subs(h,0)-s.diff(V,h).subs(h,0)*s.diff(U,h).subs(h,0),B)
 ck('The quadratic log coefficient equals the product coefficient because the linear coefficient vanishes',B-(s.diff(C,h).subs(h,0)**2)/2,B)
 analytic('Accumulating the commutator drift',['All matrices are real two by two and the square-root scale is positive. Their determinants are one and they tend to the identity.'],['The exact product is I+h^2B+O(h^3); the linear terms cancel. The matrix logarithm series is absolutely convergent in any submultiplicative norm for sufficiently small h.','Set h=n^-1/2. Then n log C(h)=B+O(n^-1/2), since the squared-log correction is O(n h^4).','Continuity of the matrix exponential yields C(n^-1/2)^n->exp(B). The requested entry is the exponential of the first diagonal drift.'])
 return candidate(r'U_n=\begin{pmatrix}1&'+L(a)+r'/\sqrt n\\0&1\end{pmatrix},\quad V_n=\begin{pmatrix}1&0\\'+L(b)+r'/\sqrt n&1\end{pmatrix}.\qquad\lim_{n\to\infty}\left[(U_nV_nU_n^{-1}V_n^{-1})^n\right]_{11}',A,[(s.exp(-a*b),'Reverse the order of the commutator'),(s.exp(a*b/2),'Insert a scalar Taylor factorial into the full commutator coefficient'),(s.exp(2*a*b),'Double the commutator drift'),(s.Integer(1),'Keep only the vanishing first-order change'),(s.exp(a+b),'Add individual shear entries as if the factors commuted'),(s.exp(a*a+b*b),'Replace interaction by the sum of squared shears')],[r'h=n^{-1/2},\qquad U_nV_nU_n^{-1}V_n^{-1}='+L(C),r'C(h)=I+h^2B+O(h^3),\qquad B='+L(B),T('The matrix logarithm converges near the identity. Its quadratic coefficient is unchanged because the linear coefficient vanished.'),r'n\ln C(n^{-1/2})=B+O(n^{-1/2})',r'C(n^{-1/2})^n\longrightarrow e^B=\begin{pmatrix}'+L(A)+r'&0\\0&'+L(s.exp(-a*b))+r'\end{pmatrix}'],'noncommuting-shear-loop-second-order-exponential-limit')

@register('limits','hilbert-determinant-rate','Cauchy-determinant-logarithmic-energy','exact-Cauchy-factorization-and-singular-log-Riemann-sums','A determinant of growing dimension is too small for entrywise limits. Its exact Cauchy factorization turns the quadratic logarithmic scale into two integrable singular energy sums.','The differentiation Hilbert representer solves a fixed finite Gram system; this measures a growing determinant and requires a two-dimensional asymptotic cancellation.',[{'caseId':'interval-'+str(L0)+'-exponent-'+str(alpha),'length':str(L0),'alpha':str(alpha),'purpose':'Change the interval scale and endpoint moment weight; the latter must be shown lower-order rather than silently dropped.'} for L0,alpha in [(1,1),(2,1),(R(1,2),2),(3,R(1,2)),(R(3,2),3),(4,2),(R(2,3),R(3,2)),(5,4)]],['Cauchy determinants','factorials','Riemann sums','logarithmic singularities'])
def hilbert_rate(case):
 length=R(case['length']);alpha=R(case['alpha']);A=length/4
 for N in [2,3,4,5]:
  M=s.Matrix(N,N,lambda i,j:1/(s.Integer(i+j)+alpha));prod=s.prod(s.factorial(j)**2 for j in range(N))/s.prod(i+j+alpha for i in range(N) for j in range(N))
  ck('Independent exact determinant agrees with Cauchy factorization at size '+str(N),M.det(),prod)
 u,v=s.symbols('u v',positive=True)
 ck('The numerator logarithmic energy integral',2*s.integrate((1-u)*s.log(u),(u,0,1)),-R(3,2))
 ck('The denominator double logarithmic energy integral',s.integrate(s.integrate(s.log(u+v),(u,0,1)),(v,0,1)),2*s.log(2)-R(3,2))
 analytic('Quadratic logarithmic determinant scale',['The moment exponent is strictly positive, so the matrix is a positive-definite Gram matrix and its determinant has a positive real root.'],['Factor the interval powers from rows and columns: the total power is n(n-1)+alpha n. The remaining Cauchy determinant is product(j!)^2 divided by product(i+j+alpha).','The numerator logarithm, divided by n^2, equals ln n plus the integral2 integral_0^1(1-u)ln u, up to o(1).','The denominator similarly equals ln n plus the unit-square integral ln(u+v), up to o(1). The logarithmic singularities are integrable; truncation near the endpoints and monotone integral bounds control them uniformly. The fixed positive shift alpha changes only an o(n^2) term.','Subtracting cancels ln n and leaves -2ln2. The interval factor adds ln(length), giving the asserted root limit.'])
 return candidate(r'H_n=\left(\int_0^{'+L(length)+r'}x^{i+j+'+L(alpha-1)+r'}\,\mathrm dx\right)_{i,j=0}^{n-1}.\qquad\lim_{n\to\infty}(\det H_n)^{1/n^2}',A,[(length/16,'Apply the logarithmic determinant cancellation twice'),(length/2,'Lose a factor two in the Cauchy interaction energy'),(length/8,'Add an extra half-scale factor'),(length,'Discard the determinant energy and keep only interval scaling'),(1/(4*length),'Invert the interval scaling'),(length**2/4,'Use twice the interval exponent'),(length/4**alpha,'Treat the fixed endpoint exponent as a leading quadratic multiplier')],[r'(H_n)_{ij}=\frac{'+L(length)+r'^{i+j+'+L(alpha)+r'}}{i+j+'+L(alpha)+r'}',r'\det H_n='+L(length)+r'^{n(n-1)+'+L(alpha)+r'n}\frac{\prod_{j=0}^{n-1}(j!)^2}{\prod_{i,j=0}^{n-1}(i+j+'+L(alpha)+r')}',T('Take logarithms. The two leading logarithms of n cancel; their finite parts are integrable logarithmic Riemann sums.'),r'\frac2{n^2}\sum_{j=0}^{n-1}\ln(j!)-\ln n\longrightarrow2\int_0^1(1-u)\ln u\,\mathrm du=-\frac32',r'\frac1{n^2}\sum_{i,j=0}^{n-1}\ln(i+j+'+L(alpha)+r')-\ln n\longrightarrow\int_0^1\!\int_0^1\ln(u+v)\,\mathrm du\,\mathrm dv=2\ln2-\frac32',T('Truncate the logarithmic singularities and use monotone integral bounds on the small omitted regions; the fixed positive endpoint shift contributes only lower order.'),r'\frac{\ln\det H_n}{n^2}\longrightarrow\ln('+L(length)+r')-2\ln2'],'growing-moment-Cauchy-determinant-quadratic-log-scale')
